(function(root){
  'use strict';
  function preview({state,cards,button,fmtDate,recommendAction,validate=false,model=null}){
    const C=root.LernpassCore,error=validate?C.validatePlan(state.plan):'';
    if(error)return `<div class="notice warning" role="status">${error}</div>`;
    const p=model||C.planning(cards,state),f=p.forecast,choice=[15,30,45,60,90].find(n=>n>=p.recommendedMinutes&&n>state.plan.minutes);
    return `<div class="plan-preview"><div class="eyebrow">DEINE PLANVORSCHAU</div><h3>${p.examDate?'Ausgerichtet auf den '+fmtDate(p.examDate):'Dein '+state.plan.days+'-Tage-Rahmen'}</h3><div class="preview-summary"><span><b>${p.dates.length}</b> Lerntage übrig</span><span><b>${f.newCount}</b> neue Fragen eingeplant</span><span><b>${p.reviewDates.length}</b> Lerntage Abschlussrunde</span></div>${f.unintroduced&&!p.finished?`<div class="notice warning">Bei dieser Zeitplanung bleiben voraussichtlich ${f.unintroduced} Fragen ohne erste Bewertung. Wähle mehr Lernzeit oder zusätzliche Lerntage.</div>`:''}${p.shortfall&&!p.finished?`<p class="small-muted">Grob ${p.need} Minuten Übungsbedarf stehen ${p.budget} Minuten eingeplanter Zeit gegenüber.${p.recommendedMinutes?' Richtwert: '+p.recommendedMinutes+' Minuten pro verbleibendem Lerntag.':''}</p>`:''}${recommendAction&&choice&&(p.shortfall||f.unintroduced)?button(recommendAction,choice+' Minuten pro Lerntag übernehmen','text-link',`data-minutes="${choice}"`):''}<details class="forecast-days"><summary>Nächste ${Math.min(7,f.rows.length)} Lerntage ansehen</summary><div>${f.rows.slice(0,7).map(r=>`<div class="forecast-row"><span><b>${fmtDate(r.day,true)}</b><small>${r.phase}</small></span><span>${r.newCount} neu · ${r.reviews} Wiederholungen</span><strong>ca. ${r.minutes} Min.</strong></div>`).join('')||'<p>Im verbleibenden Zeitraum ist kein Lerntag ausgewählt.</p>'}</div></details><p class="forecast-note">${f.assumption} Zeitbedarf und vollständige Bearbeitung sind Schätzungen. Dein tatsächlicher Lernstand bestimmt die nächsten Einheiten.</p></div>`;
  }
  function render({state,cards,button,icon,fmtDate}){
    const p=root.LernpassCore.planning(cards,state),fixed=Boolean(p.examDate);
    return `<section class="panel deadline-panel"><div class="section-top"><div><div class="eyebrow">${fixed?'DEIN PRÜFUNGSZIEL':'DEIN ZEITPLAN'}</div><h2>${fixed?'Bis zur Prüfung am '+fmtDate(p.examDate,true):'Wann ist deine Prüfung?'}</h2></div>${button('exam-plan',icon('calendar')+(fixed?' Lernplan anpassen':' Prüfungstermin & Lernplan'),'text-link')}</div><p>${fixed?`Letzter Lerntag: ${fmtDate(p.end)}. ${p.reviewDates.length} ${p.reviewDates.length===1?'Lerntag ist':'Lerntage sind'} für die Abschlusswiederholung reserviert${state.plan.reviewAuto?' und automatisch auf deine Lerntage abgestimmt':''}.`:'Trage deinen echten Prüfungstermin ein. Der Lernpass verteilt den verbleibenden Stoff, priorisiert Fehler und plant die Abschlusswiederholung ein.'}</p><div class="deadline-metrics"><div><b>${p.untested}</b><span>Fragen ohne erste Bewertung</span></div><div><b>${p.dates.length}</b><span>verbleibende Lerntage</span></div><div><b>${p.target}</b><span>${p.finalReview?'nur bekannten Stoff festigen':'weitere neue Fragen heute als Ziel'}</span></div></div>${fixed?`<div class="deadline-phase">${icon(p.finalReview?'check':'learn')}<span>${p.phase}${p.finalStart&&!p.finished?' · Abschlussrunde ab '+fmtDate(p.finalStart,true):''}</span></div>`:''}${p.missed&&!p.finished?`<p class="small-muted">An ${p.missed} geplanten ${p.missed===1?'Tag wurde':'Tagen wurde'} keine Lernaktivität gespeichert. Die offenen Fragen sind auf die verbleibenden Tage neu verteilt.</p>`:''}${p.finished?'<p class="small-muted">Dein geplanter Zeitraum ist beendet. Du kannst weiter üben oder einen neuen Prüfungstermin festlegen.</p>':preview({state,cards,button,fmtDate,model:p})}</section>`;
  }
  const api={render,preview};root.LernpassPlannerUI=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
